import type { ArrayPredicate, ArrayMapper, Comparator, SortConfig, GroupedResult, ChunkResult, UniqueByKey } from '../types';
/**
 * Returns the first element of an array
 * @param arr - The array
 * @returns The first element or undefined
 */
export declare function first<T>(arr: T[]): T | undefined;
/**
 * Returns the last element of an array
 * @param arr - The array
 * @returns The last element or undefined
 */
export declare function last<T>(arr: T[]): T | undefined;
/**
 * Returns an array with the first n elements
 * @param arr - The array
 * @param n - Number of elements to take
 * @returns Array with first n elements
 */
export declare function take<T>(arr: T[], n: number): T[];
/**
 * Returns an array without the first n elements
 * @param arr - The array
 * @param n - Number of elements to drop
 * @returns Array without first n elements
 */
export declare function drop<T>(arr: T[], n: number): T[];
/**
 * Returns an array with the last n elements
 * @param arr - The array
 * @param n - Number of elements to take
 * @returns Array with last n elements
 */
export declare function takeLast<T>(arr: T[], n: number): T[];
/**
 * Returns an array without the last n elements
 * @param arr - The array
 * @param n - Number of elements to drop
 * @returns Array without last n elements
 */
export declare function dropLast<T>(arr: T[], n: number): T[];
/**
 * Filters out null and undefined values from an array
 * @param arr - The array
 * @returns Array without null or undefined values
 */
export declare function compact<T>(arr: (T | null | undefined)[]): T[];
/**
 * Filters out falsy values from an array
 * @param arr - The array
 * @returns Array without falsy values
 */
export declare function truthy<T>(arr: (T | false | 0 | '' | null | undefined)[]): T[];
/**
 * Returns unique values from an array
 * @param arr - The array
 * @param key - Optional key or function to determine uniqueness
 * @returns Array with unique values
 */
export declare function unique<T>(arr: T[], key?: UniqueByKey<T>): T[];
/**
 * Flattens a nested array to a specified depth
 * @param arr - The array to flatten
 * @param depth - The depth to flatten
 * @returns Flattened array
 */
export declare function flatten<T>(arr: unknown[], depth?: number): T[];
/**
 * Flattens a nested array completely
 * @param arr - The array to flatten
 * @returns Completely flattened array
 */
export declare function flattenDeep<T>(arr: unknown[]): T[];
/**
 * Splits an array into chunks of specified size
 * @param arr - The array
 * @param size - Size of each chunk
 * @returns Array of chunks
 */
export declare function chunk<T>(arr: T[], size: number): ChunkResult<T>;
/**
 * Groups array elements by a key
 * @param arr - The array
 * @param key - Key to group by or function returning the key
 * @returns Grouped object
 */
export declare function groupBy<T, K extends string | number | symbol>(arr: T[], key: keyof T | ((item: T) => K)): GroupedResult<T, K>;
/**
 * Finds an element in an array
 * @param arr - The array
 * @param predicate - Predicate function
 * @returns The found element or undefined
 */
export declare function find<T>(arr: T[], predicate: ArrayPredicate<T>): T | undefined;
/**
 * Finds the index of an element in an array
 * @param arr - The array
 * @param predicate - Predicate function
 * @returns The index or -1 if not found
 */
export declare function findIndex<T>(arr: T[], predicate: ArrayPredicate<T>): number;
/**
 * Finds the last element matching a predicate
 * @param arr - The array
 * @param predicate - Predicate function
 * @returns The found element or undefined
 */
export declare function findLast<T>(arr: T[], predicate: ArrayPredicate<T>): T | undefined;
/**
 * Maps array elements using a mapper function
 * @param arr - The array
 * @param mapper - Mapper function
 * @returns Mapped array
 */
export declare function map<T, R>(arr: T[], mapper: ArrayMapper<T, R>): R[];
/**
 * Filters array elements using a predicate
 * @param arr - The array
 * @param predicate - Predicate function
 * @returns Filtered array
 */
export declare function filter<T>(arr: T[], predicate: ArrayPredicate<T>): T[];
/**
 * Sorts an array
 * @param arr - The array
 * @param comparator - Comparator function or sort configs
 * @returns Sorted array
 */
export declare function sort<T>(arr: T[], comparator?: Comparator<T> | SortConfig<T>[]): T[];
/**
 * Reverses an array without mutating
 * @param arr - The array
 * @returns Reversed array
 */
export declare function reverse<T>(arr: T[]): T[];
/**
 * Shuffles an array randomly
 * @param arr - The array
 * @returns Shuffled array
 */
export declare function shuffle<T>(arr: T[]): T[];
/**
 * Returns the intersection of two arrays
 * @param arr1 - First array
 * @param arr2 - Second array
 * @returns Array with common elements
 */
export declare function intersection<T>(arr1: T[], arr2: T[]): T[];
/**
 * Returns the difference between two arrays
 * @param arr1 - First array
 * @param arr2 - Second array
 * @returns Array with elements in arr1 but not in arr2
 */
export declare function difference<T>(arr1: T[], arr2: T[]): T[];
/**
 * Returns the union of two arrays
 * @param arr1 - First array
 * @param arr2 - Second array
 * @returns Array with all unique elements
 */
export declare function union<T>(arr1: T[], arr2: T[]): T[];
/**
 * Zips multiple arrays together
 * @param arrays - Arrays to zip
 * @returns Zipped array
 */
export declare function zip<T>(...arrays: T[][]): T[][];
/**
 * Calculates the sum of numbers in an array
 * @param arr - Array of numbers
 * @returns Sum of all numbers
 */
export declare function sum(arr: number[]): number;
/**
 * Calculates the average of numbers in an array
 * @param arr - Array of numbers
 * @returns Average value
 */
export declare function average(arr: number[]): number;
/**
 * Returns the minimum value in an array
 * @param arr - Array of numbers
 * @returns Minimum value
 */
export declare function min(arr: number[]): number;
/**
 * Returns the maximum value in an array
 * @param arr - Array of numbers
 * @returns Maximum value
 */
export declare function max(arr: number[]): number;
/**
 * Creates a range of numbers
 * @param start - Start value
 * @param end - End value
 * @param step - Step value
 * @returns Array of numbers
 */
export declare function range(start: number, end: number, step?: number): number[];
/**
 * Checks if an array includes all specified values
 * @param arr - The array
 * @param values - Values to check
 * @returns True if all values are included
 */
export declare function includesAll<T>(arr: T[], values: T[]): boolean;
/**
 * Checks if an array includes any of the specified values
 * @param arr - The array
 * @param values - Values to check
 * @returns True if any value is included
 */
export declare function includesAny<T>(arr: T[], values: T[]): boolean;
/**
 * Partitions an array into two based on a predicate
 * @param arr - The array
 * @param predicate - Predicate function
 * @returns Tuple of arrays matching and not matching the predicate
 */
export declare function partition<T>(arr: T[], predicate: ArrayPredicate<T>): [T[], T[]];
/**
 * Counts occurrences of each value in an array
 * @param arr - The array
 * @returns Object with value counts
 */
export declare function countBy<T>(arr: T[], key?: keyof T | ((item: T) => string | number)): Record<string, number>;
/**
 * Safely accesses an array element at a given index
 * @param arr - The array
 * @param index - The index (supports negative)
 * @returns Element at index or undefined
 */
export declare function at<T>(arr: T[], index: number): T | undefined;
/**
 * Removes duplicates and flattens an array
 * @param arr - The nested array
 * @returns Flattened array with unique values
 */
export declare function uniqFlat<T>(arr: unknown[]): T[];
/**
 * Checks if two arrays are equal
 * @param arr1 - First array
 * @param arr2 - Second array
 * @returns True if arrays are equal
 */
export declare function isEqual<T>(arr1: T[], arr2: T[]): boolean;
/**
 * Inserts an element at a specific index
 * @param arr - The array
 * @param index - Index to insert at
 * @param items - Items to insert
 * @returns New array with inserted items
 */
export declare function insertAt<T>(arr: T[], index: number, ...items: T[]): T[];
/**
 * Removes elements at specific indices
 * @param arr - The array
 * @param indices - Indices to remove
 * @returns New array without the removed elements
 */
export declare function removeAt<T>(arr: T[], ...indices: number[]): T[];
/**
 * Moves an element from one index to another
 * @param arr - The array
 * @param from - Source index
 * @param to - Target index
 * @returns New array with moved element
 */
export declare function move<T>(arr: T[], from: number, to: number): T[];
/**
 * Swaps two elements in an array
 * @param arr - The array
 * @param i - First index
 * @param j - Second index
 * @returns New array with swapped elements
 */
export declare function swap<T>(arr: T[], i: number, j: number): T[];
/**
 * Rotates array elements
 * @param arr - The array
 * @param n - Number of positions to rotate (positive = right, negative = left)
 * @returns Rotated array
 */
export declare function rotate<T>(arr: T[], n: number): T[];
/**
 * Fills an array with a value
 * @param length - Array length
 * @param value - Value or function to generate values
 * @returns Filled array
 */
export declare function fill<T>(length: number, value: T | ((index: number) => T)): T[];
/**
 * Checks if array is sorted
 * @param arr - The array
 * @param comparator - Optional comparator
 * @returns True if sorted
 */
export declare function isSorted<T>(arr: T[], comparator?: Comparator<T>): boolean;
/**
 * Returns a sample of random elements from an array
 * @param arr - The array
 * @param count - Number of elements to sample
 * @returns Array of sampled elements
 */
export declare function sample<T>(arr: T[], count?: number): T[];
/**
 * Creates a frequency map of array elements
 * @param arr - The array
 * @returns Map with element frequencies
 */
export declare function frequency<T>(arr: T[]): Map<T, number>;
/**
 * Returns elements that appear only once
 * @param arr - The array
 * @returns Array of unique occurrences
 */
export declare function uniqueOnly<T>(arr: T[]): T[];
/**
 * Returns elements that appear more than once
 * @param arr - The array
 * @returns Array of duplicate elements
 */
export declare function duplicates<T>(arr: T[]): T[];
/**
 * Converts array-like or iterable to array
 * @param source - Source iterable or array-like
 * @returns Array
 */
export declare function toArray<T>(source: Iterable<T> | ArrayLike<T>): T[];
/**
 * Removes falsy values and flattens
 * @param arr - The array
 * @returns Cleaned and flattened array
 */
export declare function clean<T>(arr: unknown[]): T[];
/**
 * Ensures a value is an array
 * @param value - The value
 * @returns Array containing the value or the value itself if already an array
 */
export declare function ensureArray<T>(value: T | T[]): T[];
/**
 * Returns the nth element supporting negative index
 * @param arr - The array
 * @param n - The index
 * @returns Element at index
 */
export declare function nth<T>(arr: T[], n: number): T | undefined;
/**
 * Checks if all elements satisfy a predicate
 * @param arr - The array
 * @param predicate - Predicate function
 * @returns True if all satisfy
 */
export declare function every<T>(arr: T[], predicate: ArrayPredicate<T>): boolean;
/**
 * Checks if some elements satisfy a predicate
 * @param arr - The array
 * @param predicate - Predicate function
 * @returns True if some satisfy
 */
export declare function some<T>(arr: T[], predicate: ArrayPredicate<T>): boolean;
/**
 * Returns none if predicate matches no elements
 * @param arr - The array
 * @param predicate - Predicate function
 * @returns True if none match
 */
export declare function none<T>(arr: T[], predicate: ArrayPredicate<T>): boolean;
